        h = 0
        while h < len(q):
            v = q[h]
            h += 1
            for c in (L[v], R[v]):
                if c >= 0:
                    out.append('0')
                    q.append(c)
                else:
                    out.append('null')
        while out[-1] == 'null':
            out.pop()
        return ' '.join(out)
    def build(n, spine=0, zigzag=False):
        L = [-1] * n
        R = [-1] * n
        free = [0]
        for i in range(1, n):
            if i <= spine:
                p = i - 1
                if zigzag:
                    side = 0 if i % 2 else 1
                else:
                    side = rng.randrange(2)
                if (L if side == 0 else R)[p] >= 0:
                    side = 1 - side
                (L if side == 0 else R)[p] = i
