                side = rng.randrange(2)
            else:
                side = 0 if L[p] < 0 else 1
            (L if side == 0 else R)[p] = i
            if L[p] >= 0 and R[p] >= 0:
                free[idx] = free[-1]
                free.pop()
            free.append(i)
        return L, R
